from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype
from taf.ul.kpi_selector.utilities.kpi_logger import log_suppression


class ResetRf(OperationPrototype):
    def __init__(self, bts, init_ru_id, admin_ru_id):
        super(ResetRf, self).__init__(bts)
        self.init_ru_id = str(init_ru_id) if init_ru_id is not None else init_ru_id
        self.admin_ru_id = str(admin_ru_id) if admin_ru_id is not None else admin_ru_id
        self.operation_details = {
            "Timeout": 0,
            "Operation": "RF Reset",
            "Start point": "Last cell down",
            "End point": "First cell up",
            "Requirement": "-",
        }

    def get_kpi(self):
        """
        Gets RF lock procedure timeout
        :return: dictionary with timeout, requirement and operation description for reset rf
        :rtype: dict
        """
        log_suppression("There was no configuration found in Gates tool for Your setup, "
                        "returning default timeout for reset rf. Please, do not base Your pronto "
                        "on that value.")

        self.operation_details["Timeout"] += 500

        return self.operation_details
